#!/usr/bin/env node
// Validates a .http file generated by the http-samples skill against
// references/http-conventions.md.
//
// Usage: node validate-http-file.js <path-to-.http>
// Exit code 0 when the file is valid, 1 when it is not.

const fs = require("node:fs");
const path = require("node:path");

const BASE_URL = "http://localhost:5033";
const METHODS = ["GET", "POST", "PUT", "PATCH", "DELETE"];
const BODY_METHODS = ["POST", "PUT", "PATCH"];

const errors = [];
const warnings = [];
let requestCount = 0;

function error(line, message) {
  errors.push({ line, message });
}

function warn(line, message) {
  warnings.push({ line, message });
}

const filePath = process.argv[2];

if (!filePath) {
  console.error("Usage: node validate-http-file.js <path-to-.http>");
  process.exit(1);
}

if (!fs.existsSync(filePath)) {
  console.error(`File not found: ${filePath}`);
  process.exit(1);
}

if (path.extname(filePath) !== ".http") {
  error(0, `Expected a .http file, got "${path.basename(filePath)}".`);
}

const raw = fs.readFileSync(filePath, "utf8");
const lines = raw.split(/\r?\n/);

if (raw.trim() === "") {
  error(0, "File is empty.");
  report();
}

// --- Variables -------------------------------------------------------------
// @name = value declarations at the top of the file.
const declared = new Set();
lines.forEach((line, i) => {
  const match = /^@([A-Za-z_][\w-]*)\s*=\s*(.*)$/.exec(line.trim());
  if (!match) return;
  const [, name, value] = match;
  if (declared.has(name)) error(i + 1, `Variable "@${name}" declared twice.`);
  declared.add(name);
  if (value.trim() === "") error(i + 1, `Variable "@${name}" has no value.`);
});

if (!declared.has("baseUrl")) {
  error(0, 'Missing "@baseUrl" variable declaration.');
} else {
  const decl = lines.find((l) => /^@baseUrl\s*=/.test(l.trim()));
  const value = decl.split("=").slice(1).join("=").trim();
  if (value !== BASE_URL) {
    error(
      lines.indexOf(decl) + 1,
      `@baseUrl should be "${BASE_URL}", got "${value}".`,
    );
  }
}

// --- Split into blocks on ### ---------------------------------------------
const blocks = [];
let current = null;

lines.forEach((line, i) => {
  if (line.startsWith("###")) {
    if (current) blocks.push(current);
    current = { label: line, labelLine: i + 1, body: [] };
    return;
  }
  if (current) current.body.push({ text: line, line: i + 1 });
});
if (current) blocks.push(current);
requestCount = blocks.length;

if (blocks.length === 0) {
  error(0, "No requests found. Each request must start with a `###` label.");
  report();
}

// --- Validate each block ---------------------------------------------------
const seenLabels = new Set();

for (const block of blocks) {
  const labelMatch = /^###\s+(\S+)\s+(\S+)\s*$/.exec(block.label);
  if (!labelMatch) {
    error(
      block.labelLine,
      `Label must be "### <METHOD> <route>", got "${block.label.trim()}".`,
    );
    continue;
  }

  const [, labelMethod, labelRoute] = labelMatch;

  if (!METHODS.includes(labelMethod)) {
    error(block.labelLine, `Unknown HTTP method "${labelMethod}" in label.`);
  }

  const labelKey = `${labelMethod} ${labelRoute}`;
  if (seenLabels.has(labelKey)) {
    error(block.labelLine, `Duplicate request "${labelKey}".`);
  }
  seenLabels.add(labelKey);

  // First non-empty line after the label is the request line.
  const requestEntry = block.body.find((entry) => entry.text.trim() !== "");
  if (!requestEntry) {
    error(block.labelLine, `Request "${labelKey}" has no request line.`);
    continue;
  }

  const requestMatch = /^(\S+)\s+(\S+)(?:\s+HTTP\/[\d.]+)?\s*$/.exec(
    requestEntry.text.trim(),
  );
  if (!requestMatch) {
    error(
      requestEntry.line,
      `Malformed request line: "${requestEntry.text.trim()}".`,
    );
    continue;
  }

  const [, method, url] = requestMatch;

  if (method !== labelMethod) {
    error(
      requestEntry.line,
      `Method "${method}" does not match the label method "${labelMethod}".`,
    );
  }

  if (!url.startsWith("{{baseUrl}}")) {
    error(
      requestEntry.line,
      `URL must start with "{{baseUrl}}", got "${url}". Do not hardcode the host.`,
    );
  }

  // Every {{var}} used must be declared.
  for (const used of url.matchAll(/\{\{(\w+)\}\}/g)) {
    if (!declared.has(used[1])) {
      error(requestEntry.line, `Undeclared variable "{{${used[1]}}}".`);
    }
  }

  // Route in the label should line up with the URL path, allowing the label
  // to use {id} where the URL uses a {{variable}}.
  const urlPath = url.replace("{{baseUrl}}", "").replace(/\{\{\w+\}\}/g, "*");
  const labelPath = labelRoute.replace(/\{[^}]+\}/g, "*");
  if (urlPath !== labelPath) {
    warn(
      block.labelLine,
      `Label route "${labelRoute}" does not match the request path "${url.replace("{{baseUrl}}", "")}".`,
    );
  }

  // --- Headers and body ----------------------------------------------------
  const rest = block.body.slice(block.body.indexOf(requestEntry) + 1);
  const blankIndex = rest.findIndex((entry) => entry.text.trim() === "");
  const headers = blankIndex === -1 ? rest : rest.slice(0, blankIndex);
  const bodyEntries = blankIndex === -1 ? [] : rest.slice(blankIndex + 1);
  const bodyText = bodyEntries
    .map((entry) => entry.text)
    .join("\n")
    .trim();

  for (const header of headers) {
    if (header.text.trim() === "") continue;
    if (!/^[\w-]+\s*:\s*\S/.test(header.text)) {
      error(header.line, `Malformed header: "${header.text.trim()}".`);
    }
  }

  const hasJsonContentType = headers.some((header) =>
    /^content-type\s*:\s*application\/json/i.test(header.text.trim()),
  );

  if (BODY_METHODS.includes(method)) {
    if (bodyText === "") {
      error(requestEntry.line, `${method} request "${labelKey}" has no body.`);
    } else {
      if (!hasJsonContentType) {
        error(
          requestEntry.line,
          `${method} request "${labelKey}" is missing "Content-Type: application/json".`,
        );
      }
      try {
        JSON.parse(bodyText);
      } catch (parseError) {
        error(
          bodyEntries[0]?.line ?? requestEntry.line,
          `Body of "${labelKey}" is not valid JSON: ${parseError.message}`,
        );
      }
    }
  } else if (bodyText !== "") {
    warn(requestEntry.line, `${method} request "${labelKey}" has a body.`);
  }
}

report();

// --- Reporting -------------------------------------------------------------
function report() {
  const name = path.basename(filePath);

  for (const item of warnings) {
    console.log(`warning ${name}:${item.line} ${item.message}`);
  }
  for (const item of errors) {
    console.log(`error   ${name}:${item.line} ${item.message}`);
  }

  if (errors.length === 0) {
    console.log(
      `OK ${name}: ${requestCount} request${requestCount === 1 ? "" : "s"} valid` +
        (warnings.length ? `, ${warnings.length} warning(s)` : ""),
    );
    process.exit(0);
  }

  console.log(`FAILED ${name}: ${errors.length} error(s)`);
  process.exit(1);
}
